// บัญชีค่าปอกกล้วยสุก — Cloudflare Worker (หน้าเว็บ + API + ฐานข้อมูล D1) ไม่มีล็อกอิน
const HTML = "<!doctype html>\n<html lang=\"th\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>บัญชีค่าปอกกล้วยสุก</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27%3E%3Crect width=%27100%27 height=%27100%27 rx=%2722%27 fill=%27%231f6f4a%27/%3E%3C/svg%3E\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Prompt:wght@500;600;700&family=Noto+Sans+Thai:wght@400;500;600&display=swap\">\n<style>\n:root{\n  color-scheme:light;\n  --bg:#f5f6f8; --card:#ffffff; --ink:#1b2430; --ink2:#566070; --ink3:#8b95a5;\n  --line:#e6e9ee; --line2:#d9dee6; --soft:#f0f2f6;\n  --brand:#1f6f4a; --brand-d:#15533a; --brand-l:#e8f4ee;\n  --amber:#b7791f; --amber-l:#fdf3e1;\n  --red:#c0392b; --red-d:#962d22; --red-l:#fdecea;\n  --blue:#2457c5; --blue-l:#e8effc;\n  --sh:0 1px 2px rgba(20,30,50,.04),0 8px 24px rgba(20,30,50,.06);\n  --f1:'Prompt','Noto Sans Thai',system-ui,sans-serif;\n  --f2:'Noto Sans Thai','Prompt',system-ui,sans-serif;\n}\n*{box-sizing:border-box}\nhtml{background:var(--bg)}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--f2);font-size:15px;line-height:1.5;\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:0 40px}\n.wrap{max-width:1180px;margin:0 auto}\nh1,h2,h3{font-family:var(--f1);margin:0;font-weight:600;letter-spacing:-.01em}\n.num{font-variant-numeric:tabular-nums;font-family:var(--f1)}\nbutton,input,select,textarea{font:inherit;color:inherit}\n\n/* top bar */\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:rgba(245,246,248,.92);backdrop-filter:blur(10px);\n  padding:14px 0 10px;display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);background:var(--bg);z-index:30}\n.brand{display:flex;align-items:center;gap:12px;min-width:0}\n.logo{width:42px;height:42px;border-radius:13px;background:linear-gradient(180deg,#2a8a5c,#1a5f40);display:grid;place-items:center;\n  box-shadow:0 3px 0 #0f3d29,0 8px 16px rgba(31,111,74,.25);color:#fff;font-family:var(--f1);font-weight:700;font-size:20px}\n.brand h1{font-size:18px;line-height:1.2}\n.brand small{color:var(--ink3);font-size:12px;display:block}\n.period{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n\n/* tabs */\n.tabs{display:flex;gap:8px;overflow-x:auto;padding:6px 2px 14px;scrollbar-width:none}\n.tabs::-webkit-scrollbar{display:none}\n.tab{flex:0 0 auto}\n\n/* 3D buttons */\n.btn{appearance:none;border:1px solid var(--line2);background:linear-gradient(#fff,#f3f5f8);color:var(--ink);\n  padding:9px 16px;border-radius:12px;cursor:pointer;font-weight:500;line-height:1.2;\n  box-shadow:0 3px 0 #cfd5de,0 6px 10px rgba(20,30,50,.07);transform:translateY(0);\n  transition:transform .08s,box-shadow .08s,filter .15s;white-space:nowrap;display:inline-flex;align-items:center;gap:6px;justify-content:center}\n.btn:hover{filter:brightness(.985)}\n.btn:active{transform:translateY(3px);box-shadow:0 0 0 #cfd5de,inset 0 2px 4px rgba(20,30,50,.12)}\n.btn:focus-visible,.inp:focus-visible{outline:2px solid var(--blue);outline-offset:2px}\n.btn.on{background:linear-gradient(#2a8a5c,#1f6f4a);color:#fff;border-color:#175a3b;box-shadow:0 3px 0 #0f3d29,0 6px 12px rgba(31,111,74,.25)}\n.btn.on:active{box-shadow:0 0 0 #0f3d29,inset 0 2px 5px rgba(0,0,0,.25)}\n.btn.pri{background:linear-gradient(#2a8a5c,#1f6f4a);color:#fff;border-color:#175a3b;box-shadow:0 3px 0 #0f3d29,0 6px 12px rgba(31,111,74,.25)}\n.btn.pri:active{box-shadow:0 0 0 #0f3d29,inset 0 2px 5px rgba(0,0,0,.25)}\n.btn.warn{background:linear-gradient(#e3a43a,#c98a1f);color:#fff;border-color:#a87215;box-shadow:0 3px 0 #85590f,0 6px 12px rgba(183,121,31,.25)}\n.btn.warn:active{box-shadow:0 0 0 #85590f,inset 0 2px 5px rgba(0,0,0,.25)}\n.btn.dan{background:linear-gradient(#fff,#fdf0ee);color:var(--red);border-color:#f0c4be;box-shadow:0 3px 0 #ebc0b9,0 6px 10px rgba(192,57,43,.1)}\n.btn.dan:active{box-shadow:0 0 0 #ebc0b9,inset 0 2px 4px rgba(192,57,43,.15)}\n.btn.sm{padding:6px 11px;border-radius:10px;font-size:13px;box-shadow:0 2px 0 #cfd5de,0 4px 8px rgba(20,30,50,.06)}\n.btn.sm:active{transform:translateY(2px)}\n.btn.ico{padding:9px 12px}\n\n/* inputs */\n.inp{border:1px solid var(--line2);background:#fff;border-radius:11px;padding:9px 12px;min-width:0;\n  box-shadow:inset 0 2px 3px rgba(20,30,50,.05)}\n.inp.sm{padding:6px 9px;border-radius:9px;font-size:14px}\nselect.inp{appearance:auto;padding-right:8px}\n.inp.r{text-align:right}\n\n/* cards */\n.card{background:var(--card);border:1px solid var(--line);border-radius:20px;box-shadow:var(--sh);padding:20px;min-width:0}\n.card h2{font-size:16px;margin-bottom:14px}\n.card .sub{color:var(--ink3);font-size:13px;margin:-8px 0 14px}\n.grid{display:grid;gap:16px}\n.g4{grid-template-columns:repeat(4,minmax(0,1fr))}\n.g2{grid-template-columns:repeat(2,minmax(0,1fr))}\n.g3{grid-template-columns:repeat(3,minmax(0,1fr))}\n.split{grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);align-items:start}\n@media(max-width:900px){.g4{grid-template-columns:repeat(2,minmax(0,1fr))}.g3,.split{grid-template-columns:minmax(0,1fr)}}\n@media(max-width:520px){.g4,.g2{grid-template-columns:minmax(0,1fr)}.card{padding:16px}}\n\n.kpi{position:relative;overflow:hidden}\n.kpi .lb{color:var(--ink2);font-size:13px}\n.kpi .v{font-family:var(--f1);font-size:28px;font-weight:600;margin-top:4px;font-variant-numeric:tabular-nums;line-height:1.2}\n.kpi .u{font-size:13px;color:var(--ink3);font-weight:400;margin-left:4px}\n.kpi .dot{position:absolute;right:16px;top:16px;width:10px;height:10px;border-radius:50%}\n\n/* employee chip */\n.avatar{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;color:#fff;font-family:var(--f1);font-weight:600;flex:0 0 auto;\n  box-shadow:0 2px 0 rgba(0,0,0,.2)}\n.avatar.lg{width:52px;height:52px;border-radius:16px;font-size:22px}\n.ecard{display:flex;flex-direction:column;gap:12px}\n.ehead{display:flex;gap:12px;align-items:center;min-width:0}\n.ehead b{display:block;font-family:var(--f1);font-weight:500;overflow-wrap:anywhere}\n.ehead span{color:var(--ink3);font-size:12px}\n.rows{display:flex;flex-direction:column;gap:6px}\n.rows div{display:flex;justify-content:space-between;gap:10px;font-size:14px}\n.rows div span:first-child{color:var(--ink2)}\n.rows .net{border-top:1px dashed var(--line2);padding-top:10px;margin-top:4px;font-weight:600;font-size:16px}\n.neg{color:var(--red)}.pos{color:var(--brand)}\n.pill{display:inline-flex;align-items:center;gap:5px;padding:3px 10px;border-radius:99px;font-size:12px;font-weight:500;background:var(--soft);color:var(--ink2)}\n.pill.ok{background:var(--brand-l);color:var(--brand-d)}\n.pill.wait{background:var(--amber-l);color:var(--amber)}\n.bar{height:8px;border-radius:99px;background:var(--soft);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:99px}\n\n/* tables */\n.tw{overflow-x:auto;border:1px solid var(--line);border-radius:14px}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth{background:#fafbfc;color:var(--ink2);font-weight:500;text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;font-size:13px;position:sticky;top:0}\ntd{padding:6px 12px;border-bottom:1px solid var(--line);white-space:nowrap}\ntr:last-child td{border-bottom:0}\ntd.r,th.r{text-align:right}\ntr.hol td{background:#fdf6f5}\ntr.sun td:first-child{color:var(--red)}\ntr.tot td{background:var(--brand-l);font-weight:600;color:var(--brand-d)}\ntfoot td{background:var(--brand-l);font-weight:600;color:var(--brand-d);border-top:1px solid var(--line2)}\n.scroll{max-height:560px;overflow:auto}\n.empty{color:var(--ink3);text-align:center;padding:26px 8px;font-size:14px}\n\n/* modal */\n.mask{position:fixed;inset:0;background:rgba(20,30,50,.35);z-index:50;display:grid;place-items:center;padding:16px;overflow:auto}\n.modal{background:#fff;border-radius:22px;max-width:460px;width:100%;padding:24px;box-shadow:0 24px 60px rgba(20,30,50,.3)}\n.modal h2{font-size:18px;margin-bottom:14px}\n.field{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.field label{font-size:13px;color:var(--ink2)}\n.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n.mt{margin-top:16px}\n.muted{color:var(--ink3);font-size:13px}\n.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:#1b2430;color:#fff;padding:10px 18px;border-radius:12px;z-index:60;font-size:14px;box-shadow:0 8px 24px rgba(0,0,0,.25)}\n.swatches{display:flex;gap:6px;flex-wrap:wrap}\n.sw{width:26px;height:26px;border-radius:8px;border:2px solid #fff;box-shadow:0 0 0 1px var(--line2),0 2px 0 rgba(0,0,0,.15);cursor:pointer;padding:0}\n.sw.sel{box-shadow:0 0 0 2px var(--ink)}\n.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:13px;color:var(--ink2);margin-bottom:10px}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px}\nsvg text{font-family:var(--f2)}\n.slip{white-space:pre-wrap;background:var(--soft);border-radius:12px;padding:14px;font-size:14px;line-height:1.7;max-height:50vh;overflow:auto}\n.login{max-width:380px;margin:8vh auto 0}\n.pill.bad{background:var(--red-l);color:var(--red-d)}\n#acct{gap:8px}\n</style>\n\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"top\">\n    <div class=\"brand\">\n      <div class=\"logo\">ก</div>\n      <div><h1>บัญชีค่าปอกกล้วยสุก</h1><small>แม่ดอนรุ่งเรือง ฟู้ดส์</small></div>\n    </div>\n    <div class=\"row\" style=\"gap:12px\"><div class=\"period\" id=\"period\"></div><div class=\"row\" id=\"acct\"></div></div>\n  </div>\n  <div class=\"tabs\" id=\"tabs\"></div>\n  <div id=\"view\"></div>\n</div>\n<div id=\"layer\"></div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\n<script>\n\"use strict\";\n/* ---------- ค่าคงที่ ---------- */\nvar KEY='banana-peel-v1';\nvar MTH=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];\nvar MS=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];\nvar DN=['อา','จ','อ','พ','พฤ','ศ','ส'];\nvar COLORS=['#1f6f4a','#c0392b','#2457c5','#7b3fa0','#b7791f','#0f8a96','#d6457a','#5a6472'];\nvar SEED_YEAR=2026; // ข้อมูลเดิมในไฟล์ = ปี 2569\nvar TYPES={adv:{n:'เบิกล่วงหน้า',sign:-1},ded:{n:'หักอื่นๆ',sign:-1},add:{n:'เงินเพิ่ม / โบนัส',sign:1}};\n\n/* ---------- ตัวช่วย ---------- */\nfunction $(s,r){return (r||document).querySelector(s)}\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\nfunction pad(n){return n<10?'0'+n:''+n}\nfunction uid(){return Math.random().toString(36).slice(2,9)}\nfunction num(v){var n=parseFloat(String(v).replace(/,/g,''));return isFinite(n)?n:0}\nfunction fmt(n,d){n=n||0;return n.toLocaleString('th-TH',{minimumFractionDigits:d==null?2:d,maximumFractionDigits:d==null?2:d})}\nfunction kg(n){return fmt(n,(n%1===0)?0:1)}\nfunction dim(y,m){return new Date(y,m,0).getDate()}\nfunction dkey(y,m,d){return y+'-'+pad(m)+'-'+pad(d)}\nfunction be(y){return y+543}\nfunction init1(name){var s=String(name||'').replace(/^(นาย|นางสาว|นาง|น\\.ส\\.|ด\\.ช\\.|ด\\.ญ\\.)\\s*/,'').trim();return s?s.charAt(0):'?'}\nfunction shortName(n){var p=String(n||'').replace(/^(นาย|นางสาว|นาง)\\s*/,'').trim().split(/\\s+/);return p[0]||n}\n\n/* ---------- สถานะ + ซิงก์กับ Cloudflare D1 ---------- */\nvar S=null;\nvar API={rev:0};\nvar BASE=null,syncTimer=null,retryTimer=null,syncing=false,syncState='saved',syncMsg='';\nfunction tget(k){try{return localStorage.getItem(k)}catch(e){return null}}\nfunction tset(k,v){try{localStorage.setItem(k,v)}catch(e){}}\nfunction uiLoad(){\n  var u={};try{u=JSON.parse(tget('bp-ui')||'{}')}catch(e){}\n  var n=new Date();\n  return {tab:u.tab||'dash',emp:u.emp||null,y:u.y||n.getFullYear(),m:u.m||n.getMonth()+1};\n}\nfunction saveUi(){if(S)tset('bp-ui',JSON.stringify(S.ui))}\nfunction toast(t){\n  var el=document.createElement('div');el.className='toast';el.textContent=t;document.body.appendChild(el);\n  setTimeout(function(){el.remove()},2200);\n}\nfunction emp(id){return S.emps.filter(function(e){return e.id===id})[0]}\n\nfunction fromServer(d){\n  var ui=S?S.ui:uiLoad();\n  var st={emps:d.emps.map(function(e){return {id:e.id,name:e.name,color:e.color,note:e.note||''}}),recs:{},paid:{},defPrice:d.defPrice||1.5,ui:ui,\n    mov:d.mov.map(function(x){return {id:x.id,emp:x.emp,date:x.date,type:x.type,amt:x.amt,note:x.note||''}})};\n  st.emps.forEach(function(e){st.recs[e.id]={}});\n  d.recs.forEach(function(r){var R=st.recs[r[0]];if(R)R[r[1]]={q:r[2],p:r[3],h:r[4]?1:0}});\n  d.paid.forEach(function(k){st.paid[k]=1});\n  if(!st.emps.some(function(e){return e.id===ui.emp}))ui.emp=st.emps[0]&&st.emps[0].id;\n  return st;\n}\nfunction load2(){S.mov=S.mov||[];S.paid=S.paid||{};S.recs=S.recs||{};S.ui=S.ui||uiLoad();if(!S.defPrice)S.defPrice=1.5}\n\n/* ภาพถ่ายข้อมูล เพื่อเทียบหาส่วนที่เปลี่ยน */\nfunction snap(st){\n  var o={emps:{},recs:{},mov:{},paid:{},defPrice:st.defPrice};\n  st.emps.forEach(function(e,i){o.emps[e.id]=JSON.stringify([e.name,e.color,e.note||'',i+1])});\n  st.emps.forEach(function(e){var R=st.recs[e.id]||{};for(var k in R){var r=R[k];o.recs[e.id+'|'+k]=JSON.stringify([num(r.q),num(r.p),r.h?1:0])}});\n  st.mov.forEach(function(x){o.mov[x.id]=JSON.stringify([x.emp,x.date,x.type,num(x.amt),x.note||''])});\n  for(var k in st.paid)if(st.paid[k])o.paid[k]=1;\n  return o;\n}\n/* คืนรายการคำสั่งแบน [[ชนิด, ข้อมูล], ...] เรียงตามลำดับที่ต้องส่ง */\nfunction diffOps(a,b){\n  var ops=[],gone={},id,k,i,v;\n  for(id in a.emps)if(!(id in b.emps)){gone[id]=1;ops.push(['ed',id])}\n  for(id in b.emps)if(a.emps[id]!==b.emps[id]){v=JSON.parse(b.emps[id]);ops.push(['eu',{id:id,name:v[0],color:v[1],note:v[2],sort:v[3]}])}\n  for(k in a.recs)if(!(k in b.recs)){i=k.indexOf('|');if(!gone[k.slice(0,i)])ops.push(['rd',[k.slice(0,i),k.slice(i+1)]])}\n  for(k in b.recs)if(a.recs[k]!==b.recs[k]){i=k.indexOf('|');v=JSON.parse(b.recs[k]);ops.push(['ru',[k.slice(0,i),k.slice(i+1),v[0],v[1],v[2]]])}\n  for(id in a.mov)if(!(id in b.mov)&&!gone[JSON.parse(a.mov[id])[0]])ops.push(['md',id]);\n  for(id in b.mov)if(a.mov[id]!==b.mov[id]){v=JSON.parse(b.mov[id]);ops.push(['mu',{id:id,emp:v[0],date:v[1],type:v[2],amt:v[3],note:v[4]}])}\n  for(k in a.paid)if(!(k in b.paid)&&!gone[k.split('|')[0]])ops.push(['po',k]);\n  for(k in b.paid)if(!(k in a.paid))ops.push(['pn',k]);\n  if(a.defPrice!==b.defPrice)ops.push(['dp',b.defPrice]);\n  return ops;\n}\nfunction payload(ops){\n  var P={emps:{up:[],del:[]},recs:{up:[],del:[]},mov:{up:[],del:[]},paid:{on:[],off:[]}};\n  ops.forEach(function(o){var t=o[0],d=o[1];\n    if(t==='ed')P.emps.del.push(d);else if(t==='eu')P.emps.up.push(d);\n    else if(t==='rd')P.recs.del.push(d);else if(t==='ru')P.recs.up.push(d);\n    else if(t==='md')P.mov.del.push(d);else if(t==='mu')P.mov.up.push(d);\n    else if(t==='po')P.paid.off.push(d);else if(t==='pn')P.paid.on.push(d);\n    else if(t==='dp')P.defPrice=d});\n  return P;\n}\nfunction applyBase(ops,cur){\n  ops.forEach(function(o){var t=o[0],d=o[1],k;\n    if(t==='ed'){delete BASE.emps[d];['recs','mov','paid'].forEach(function(c){for(k in BASE[c]){var e=c==='mov'?JSON.parse(BASE.mov[k])[0]:k.split('|')[0];if(e===d)delete BASE[c][k]}})}\n    else if(t==='eu')BASE.emps[d.id]=cur.emps[d.id];\n    else if(t==='rd')delete BASE.recs[d[0]+'|'+d[1]];\n    else if(t==='ru')BASE.recs[d[0]+'|'+d[1]]=cur.recs[d[0]+'|'+d[1]];\n    else if(t==='md')delete BASE.mov[d];\n    else if(t==='mu')BASE.mov[d.id]=cur.mov[d.id];\n    else if(t==='po')delete BASE.paid[d];\n    else if(t==='pn')BASE.paid[d]=1;\n    else if(t==='dp')BASE.defPrice=d;\n  });\n}\n\n/* ---------- เครือข่าย (ไม่มีล็อกอิน) ---------- */\nasync function api(path,opt){\n  opt=opt||{};\n  var res;\n  try{res=await fetch(path,{method:opt.method||'GET',headers:{'content-type':'application/json'},body:opt.body})}\n  catch(e){var er=new Error('ออฟไลน์');er.status=0;throw er}\n  var d=null;try{d=await res.json()}catch(e){}\n  if(!res.ok){var e2=new Error((d&&d.error)||('error '+res.status));e2.status=res.status;throw e2}\n  return d;\n}\nfunction setSync(st,msg){\n  syncState=st;syncMsg=msg||'';\n  var el=$('#syncpill');if(!el)return;\n  var m={saved:['ok','บันทึกแล้ว'],saving:['wait','กำลังบันทึก…'],offline:['wait','ออฟไลน์ — จะลองใหม่'],error:['bad','บันทึกไม่สำเร็จ']}[st];\n  el.className='pill '+m[0];el.textContent=st==='error'&&msg?'ผิดพลาด: '+msg:m[1];\n}\nfunction save(){\n  if(!S)return;saveUi();\n  clearTimeout(syncTimer);syncTimer=setTimeout(function(){syncTimer=null;flush()},500);\n}\nasync function flush(){\n  if(syncing||!BASE||!S)return;\n  clearTimeout(retryTimer);retryTimer=null;\n  var cur=snap(S),ops=diffOps(BASE,cur);\n  if(!ops.length){setSync('saved');return}\n  syncing=true;setSync('saving');\n  try{\n    for(var i=0;i<ops.length;i+=3500){\n      var part=ops.slice(i,i+3500),r=await api('/api/sync',{method:'POST',body:JSON.stringify(payload(part))});\n      applyBase(part,cur);API.rev=r.rev;\n    }\n    syncing=false;\n    if(diffOps(BASE,snap(S)).length)flush();else setSync('saved');\n  }catch(e){\n    syncing=false;\n    if(e.status===0||e.status>=500){setSync('offline');retryTimer=setTimeout(flush,6000)}\n    else setSync('error',e.message);\n  }\n}\nwindow.addEventListener('beforeunload',function(ev){\n  if(S&&BASE&&(syncing||diffOps(BASE,snap(S)).length)){ev.preventDefault();ev.returnValue=''}\n});\n\n/* ---------- โหลดข้อมูลจาก D1 ---------- */\nfunction showError(msg){\n  $('#period').innerHTML='';$('#tabs').innerHTML='';$('#acct').innerHTML='';\n  $('#view').innerHTML='<div class=\"card login\"><div class=\"logo\" style=\"margin:0 auto 14px\">ก</div><h2 style=\"text-align:center;font-size:18px;margin-bottom:8px\">เปิดข้อมูลไม่สำเร็จ</h2>'+\n    '<p class=\"neg\" style=\"text-align:center;font-size:14px\">'+esc(msg||'')+'</p><button class=\"btn pri\" style=\"width:100%;margin-top:12px\" data-act=\"retry\">ลองใหม่</button></div>';\n}\nasync function loadRemote(first){\n  try{\n    var d=await api('/api/data');\n    API.rev=d.rev;S=fromServer(d);BASE=snap(S);\n    render();setSync('saved');\n  }catch(e){\n    if(first)showError(e.message==='ออฟไลน์'?'เชื่อมต่อเซิร์ฟเวอร์ไม่ได้ ตรวจสอบอินเทอร์เน็ต':e.message);\n  }\n}\nasync function poll(){\n  if(!S||document.hidden||syncing||syncTimer||retryTimer)return;\n  if(diffOps(BASE,snap(S)).length)return;\n  try{\n    var r=await api('/api/rev');\n    if(r.rev===API.rev)return;\n    var a=document.activeElement;\n    if(a&&/INPUT|SELECT|TEXTAREA/.test(a.tagName)&&a.closest&&a.closest('#view'))return;\n    if($('#layer').innerHTML)return;\n    await loadRemote(false);\n  }catch(e){}\n}\nfunction boot(){\n  loadRemote(true);\n  setInterval(poll,20000);\n  document.addEventListener('visibilitychange',function(){if(!document.hidden)poll()});\n}\nfunction renderAcct(){\n  $('#acct').innerHTML='<span class=\"pill\" id=\"syncpill\"></span>';\n  setSync(syncState,syncMsg);\n}\nfunction applyRO(){}\n\n/* ---------- การคำนวณ ---------- */\nfunction rec(id,y,m,d){return (S.recs[id]||{})[dkey(y,m,d)]}\nfunction dayAmt(r){return (!r||r.h)?0:num(r.q)*num(r.p)}\nfunction monthStat(id,y,m){\n  var n=dim(y,m),q=0,inc=0,days=0,hol=0;\n  for(var d=1;d<=n;d++){\n    var r=rec(id,y,m,d);if(!r)continue;\n    if(r.h){hol++;continue}\n    if(num(r.q)>0){days++;q+=num(r.q);inc+=dayAmt(r)}\n  }\n  var adv=0,ded=0,add=0,pre=m<10?y+'-0'+m:y+'-'+m;\n  S.mov.forEach(function(x){\n    if(x.emp!==id||x.date.slice(0,7)!==pre)return;\n    if(x.type==='adv')adv+=num(x.amt);else if(x.type==='ded')ded+=num(x.amt);else add+=num(x.amt);\n  });\n  return{q:q,inc:inc,days:days,hol:hol,adv:adv,ded:ded,add:add,net:inc+add-adv-ded,\n    avg:days?q/days:0,paid:!!S.paid[id+'|'+pre]};\n}\nfunction yearStat(id,y){\n  var t={q:0,inc:0,days:0,adv:0,ded:0,add:0,net:0,months:[]};\n  for(var m=1;m<=12;m++){var s=monthStat(id,y,m);t.months.push(s);\n    ['q','inc','days','adv','ded','add','net'].forEach(function(k){t[k]+=s[k]})}\n  return t;\n}\nfunction allMonth(y,m){\n  var t={q:0,inc:0,adv:0,ded:0,add:0,net:0,paid:0,unpaid:0};\n  S.emps.forEach(function(e){var s=monthStat(e.id,y,m);\n    ['q','inc','adv','ded','add','net'].forEach(function(k){t[k]+=s[k]});\n    if(s.paid)t.paid+=s.net;else t.unpaid+=s.net});\n  return t;\n}\n\n/* ---------- แถบบน ---------- */\nfunction renderPeriod(){\n  var ys='';for(var y=2024;y<=2040;y++)ys+='<option value=\"'+y+'\"'+(y===S.ui.y?' selected':'')+'>'+be(y)+'</option>';\n  var ms='';for(var m=1;m<=12;m++)ms+='<option value=\"'+m+'\"'+(m===S.ui.m?' selected':'')+'>'+MTH[m-1]+'</option>';\n  var showM=S.ui.tab!=='year'&&S.ui.tab!=='set';\n  $('#period').innerHTML=\n    (showM?'<button class=\"btn sm ico\" data-act=\"mprev\" aria-label=\"เดือนก่อน\">‹</button>':'')+\n    (showM?'<select class=\"inp sm\" data-act=\"selm\" aria-label=\"เดือน\">'+ms+'</select>':'')+\n    '<select class=\"inp sm\" data-act=\"sely\" aria-label=\"ปี พ.ศ.\">'+ys+'</select>'+\n    (showM?'<button class=\"btn sm ico\" data-act=\"mnext\" aria-label=\"เดือนถัดไป\">›</button>':'');\n}\nvar TABS=[['dash','ภาพรวม'],['emp','รายคน'],['pay','จ่ายเงิน'],['year','รายปี'],['set','ตั้งค่า']];\nfunction renderTabs(){\n  $('#tabs').innerHTML=TABS.map(function(t){\n    return '<button class=\"btn tab'+(S.ui.tab===t[0]?' on':'')+'\" data-act=\"tab\" data-v=\"'+t[0]+'\">'+t[1]+'</button>';\n  }).join('');\n}\n\n/* ---------- กราฟแท่งซ้อน (SVG) ---------- */\nfunction stackChart(cats,series,opt){\n  opt=opt||{};\n  var W=720,H=opt.h||220,L=44,R=8,T=10,B=26,n=cats.length;\n  var tot=cats.map(function(_,i){return series.reduce(function(a,s){return a+(s.v[i]||0)},0)});\n  var mx=Math.max.apply(null,tot.concat([1]));\n  var step=Math.pow(10,Math.floor(Math.log10(mx)));var top=Math.ceil(mx/step)*step;\n  if(top/step<2)top=step*2;\n  var iw=W-L-R,ih=H-T-B,bw=iw/n,g='';\n  for(var i=0;i<=4;i++){\n    var y=T+ih-ih*i/4,val=top*i/4;\n    g+='<line x1=\"'+L+'\" x2=\"'+(W-R)+'\" y1=\"'+y+'\" y2=\"'+y+'\" stroke=\"#e6e9ee\"/>'+\n       '<text x=\"'+(L-6)+'\" y=\"'+(y+4)+'\" text-anchor=\"end\" font-size=\"11\" fill=\"#8b95a5\">'+(val>=1000?fmt(val/1000,val%1000?1:0)+'k':fmt(val,0))+'</text>';\n  }\n  cats.forEach(function(c,i){\n    var yy=T+ih,x=L+i*bw+bw*.18,w=bw*.64;\n    series.forEach(function(s){\n      var h=ih*(s.v[i]||0)/top;if(h<=0)return;yy-=h;\n      g+='<rect x=\"'+x+'\" y=\"'+yy+'\" width=\"'+w+'\" height=\"'+h+'\" fill=\"'+s.c+'\" rx=\"'+Math.min(3,w/3)+'\"><title>'+esc(c)+' · '+esc(s.n)+': '+fmt(s.v[i],0)+'</title></rect>';\n    });\n    if(n<=16||i%2===0)g+='<text x=\"'+(x+w/2)+'\" y=\"'+(H-8)+'\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8b95a5\">'+esc(c)+'</text>';\n  });\n  return '<svg viewBox=\"0 0 '+W+' '+H+'\" width=\"100%\" role=\"img\" aria-label=\"'+esc(opt.label||'กราฟ')+'\">'+g+'</svg>';\n}\nfunction legend(){return '<div class=\"legend\">'+S.emps.map(function(e){return '<span><i style=\"background:'+e.color+'\"></i>'+esc(shortName(e.name))+'</span>'}).join('')+'</div>'}\n\n/* ---------- ภาพรวม ---------- */\nfunction vDash(){\n  var y=S.ui.y,m=S.ui.m,t=allMonth(y,m);\n  if(!S.emps.length)return '<div class=\"card empty\">ยังไม่มีพนักงาน — ไปที่แท็บ \"ตั้งค่า\" เพื่อเพิ่มรายชื่อ</div>';\n  var k=function(lb,v,u,c){return '<div class=\"card kpi\"><span class=\"dot\" style=\"background:'+c+'\"></span><div class=\"lb\">'+lb+'</div><div class=\"v\">'+v+'<span class=\"u\">'+u+'</span></div></div>'};\n  var h='<div class=\"grid g4\">'+\n    k('ปอกได้รวม',kg(t.q),'กก.','#1f6f4a')+\n    k('ค่าปอกรวม',fmt(t.inc),'บาท','#2457c5')+\n    k('เบิก / หักแล้ว',fmt(t.adv+t.ded),'บาท','#c0392b')+\n    k('ยอดจ่ายสุทธิ',fmt(t.net),'บาท','#b7791f')+'</div>';\n  var mx=Math.max.apply(null,S.emps.map(function(e){return monthStat(e.id,y,m).inc}).concat([1]));\n  h+='<h2 class=\"mt\" style=\"font-size:16px\">แต่ละคน · '+MTH[m-1]+' '+be(y)+'</h2><div class=\"grid g4 mt\" style=\"margin-top:10px\">'+\n    S.emps.map(function(e){\n      var s=monthStat(e.id,y,m);\n      return '<div class=\"card ecard\"><div class=\"ehead\"><div class=\"avatar\" style=\"background:'+e.color+'\">'+esc(init1(e.name))+'</div>'+\n        '<div style=\"min-width:0\"><b>'+esc(e.name)+'</b><span>ทำงาน '+s.days+' วัน · หยุด '+s.hol+' วัน</span></div></div>'+\n        '<div class=\"bar\"><i style=\"width:'+(s.inc/mx*100)+'%;background:'+e.color+'\"></i></div>'+\n        '<div class=\"rows\"><div><span>ปอกได้</span><span class=\"num\">'+kg(s.q)+' กก.</span></div>'+\n        '<div><span>ค่าปอก</span><span class=\"num\">'+fmt(s.inc)+'</span></div>'+\n        '<div><span>เบิก/หัก</span><span class=\"num neg\">'+(s.adv+s.ded?'−'+fmt(s.adv+s.ded):'0.00')+'</span></div>'+\n        '<div class=\"net\"><span>รับสุทธิ</span><span class=\"num\">'+fmt(s.net)+'</span></div></div>'+\n        '<div class=\"row\" style=\"justify-content:space-between\"><span class=\"pill '+(s.paid?'ok':'wait')+'\">'+(s.paid?'จ่ายแล้ว':'รอจ่าย')+'</span>'+\n        '<button class=\"btn sm\" data-act=\"goemp\" data-v=\"'+e.id+'\">ดูรายละเอียด</button></div></div>';\n    }).join('')+'</div>';\n  // กราฟรายวัน\n  var n=dim(y,m),cats=[],i;for(i=1;i<=n;i++)cats.push(''+i);\n  var ser=S.emps.map(function(e){var v=[];for(var d=1;d<=n;d++){var r=rec(e.id,y,m,d);v.push(r&&!r.h?num(r.q):0)}return{n:shortName(e.name),c:e.color,v:v}});\n  h+='<div class=\"grid g2\" style=\"margin-top:16px\"><div class=\"card\"><h2>กิโลกรัมที่ปอกแต่ละวัน</h2><div class=\"sub\">'+MTH[m-1]+' '+be(y)+'</div>'+legend()+stackChart(cats,ser,{label:'กิโลกรัมรายวัน'})+'</div>';\n  var ser2=S.emps.map(function(e){var v=[];for(var mm=1;mm<=12;mm++)v.push(monthStat(e.id,y,mm).inc);return{n:shortName(e.name),c:e.color,v:v}});\n  h+='<div class=\"card\"><h2>ค่าปอกรายเดือน ปี '+be(y)+'</h2><div class=\"sub\">บาท · รวมทุกคน</div>'+legend()+stackChart(MS,ser2,{label:'ค่าปอกรายเดือน'})+'</div></div>';\n  return h;\n}\n\n/* ---------- รายคน ---------- */\nfunction movList(id,y,m){\n  var pre=y+'-'+pad(m);\n  var L=S.mov.filter(function(x){return x.emp===id&&x.date.slice(0,7)===pre}).sort(function(a,b){return a.date<b.date?-1:1});\n  if(!L.length)return '<div class=\"empty\">ยังไม่มีรายการเบิก/หัก/เพิ่ม ในเดือนนี้</div>';\n  return '<div class=\"rows\">'+L.map(function(x){\n    var T=TYPES[x.type],d=+x.date.slice(8);\n    return '<div style=\"align-items:center;border-bottom:1px solid var(--line);padding-bottom:6px\"><span><b style=\"font-weight:500\">'+d+' '+MS[m-1]+'</b> · '+T.n+(x.note?'<br><span class=\"muted\">'+esc(x.note)+'</span>':'')+'</span>'+\n      '<span class=\"row\" style=\"flex-wrap:nowrap\"><span class=\"num '+(T.sign<0?'neg':'pos')+'\">'+(T.sign<0?'−':'+')+fmt(num(x.amt))+'</span>'+\n      '<button class=\"btn sm dan ico\" data-act=\"delmov\" data-v=\"'+x.id+'\" aria-label=\"ลบรายการ\">✕</button></span></div>';\n  }).join('')+'</div>';\n}\nfunction sumCard(id,y,m){\n  var e=emp(id),s=monthStat(id,y,m);\n  return '<div class=\"ehead\" style=\"margin-bottom:14px\"><div class=\"avatar lg\" style=\"background:'+e.color+'\">'+esc(init1(e.name))+'</div><div style=\"min-width:0\"><h2 style=\"margin:0\">'+esc(e.name)+'</h2><span class=\"muted\">'+MTH[m-1]+' '+be(y)+'</span></div></div>'+\n    '<div class=\"rows\"><div><span>ทำงาน</span><span class=\"num\">'+s.days+' วัน (หยุด '+s.hol+')</span></div>'+\n    '<div><span>ปอกได้รวม</span><span class=\"num\">'+kg(s.q)+' กก.</span></div>'+\n    '<div><span>เฉลี่ยต่อวัน</span><span class=\"num\">'+fmt(s.avg,1)+' กก.</span></div>'+\n    '<div><span>ค่าปอก</span><span class=\"num\">'+fmt(s.inc)+'</span></div>'+\n    '<div><span>เงินเพิ่ม</span><span class=\"num pos\">'+(s.add?'+'+fmt(s.add):'—')+'</span></div>'+\n    '<div><span>เบิกล่วงหน้า</span><span class=\"num neg\">'+(s.adv?'−'+fmt(s.adv):'—')+'</span></div>'+\n    '<div><span>หักอื่นๆ</span><span class=\"num neg\">'+(s.ded?'−'+fmt(s.ded):'—')+'</span></div>'+\n    '<div class=\"net\"><span>รับสุทธิ (บาท)</span><span class=\"num\">'+fmt(s.net)+'</span></div></div>';\n}\nfunction dayRow(id,y,m,d){\n  var r=rec(id,y,m,d)||{},dow=new Date(y,m-1,d).getDay(),h=!!r.h,amt=dayAmt(r);\n  var k=dkey(y,m,d);\n  return '<tr data-k=\"'+k+'\" class=\"'+(h?'hol ':'')+(dow===0?'sun':'')+'\"><td><b style=\"font-weight:500\">'+d+'</b> <span class=\"muted\">'+DN[dow]+'</span></td>'+\n    '<td class=\"r\"><input class=\"inp sm r qin\" inputmode=\"decimal\" style=\"width:90px\" data-f=\"q\" value=\"'+(h||!r.q?'':r.q)+'\" '+(h?'disabled':'')+' placeholder=\"0\"></td>'+\n    '<td class=\"r\"><input class=\"inp sm r\" inputmode=\"decimal\" style=\"width:70px\" data-f=\"p\" value=\"'+(r.p!=null?r.p:S.defPrice)+'\" '+(h?'disabled':'')+'></td>'+\n    '<td class=\"r num amt\">'+(h?'<span class=\"pill\">หยุด</span>':(amt?fmt(amt):'—'))+'</td>'+\n    '<td><button class=\"btn sm'+(h?' warn':'')+'\" data-act=\"hol\" data-v=\"'+k+'\">'+(h?'ยกเลิกหยุด':'หยุด')+'</button></td></tr>';\n}\nfunction vEmp(){\n  if(!S.emps.length)return '<div class=\"card empty\">ยังไม่มีพนักงาน</div>';\n  var id=S.ui.emp,y=S.ui.y,m=S.ui.m,n=dim(y,m);\n  var sel='<div class=\"tabs\" style=\"padding-top:0\">'+S.emps.map(function(e){\n    return '<button class=\"btn tab'+(e.id===id?' on':'')+'\" data-act=\"pick\" data-v=\"'+e.id+'\">'+esc(shortName(e.name))+'</button>'}).join('')+'</div>';\n  var rows='';for(var d=1;d<=n;d++)rows+=dayRow(id,y,m,d);\n  return sel+'<div class=\"grid split\"><div class=\"card\"><div class=\"row\" style=\"justify-content:space-between;margin-bottom:12px\"><h2 style=\"margin:0\">บันทึกรายวัน</h2>'+\n    '<div class=\"row\"><button class=\"btn sm\" data-act=\"setprice\">ตั้งราคา/กก. ทั้งเดือน</button><button class=\"btn sm dan\" data-act=\"clearm\">ล้างเดือนนี้</button></div></div>'+\n    '<div class=\"tw scroll\"><table><thead><tr><th>วันที่</th><th class=\"r\">กิโลกรัม</th><th class=\"r\">บาท/กก.</th><th class=\"r\">รวม (บาท)</th><th></th></tr></thead><tbody id=\"rows\">'+rows+'</tbody></table></div>'+\n    '<div class=\"muted mt\">กรอกจำนวน กก. แล้วกด Enter เพื่อไปวันถัดไป · ระบบคำนวณและบันทึกให้อัตโนมัติ</div></div>'+\n    '<div class=\"grid\"><div class=\"card\" id=\"sum\">'+sumCard(id,y,m)+'</div>'+\n    '<div class=\"card\"><div class=\"row\" style=\"justify-content:space-between;margin-bottom:12px\"><h2 style=\"margin:0\">เบิก / หัก / เพิ่ม</h2><button class=\"btn pri sm\" data-act=\"addmov\">＋ เพิ่มรายการ</button></div><div id=\"movs\">'+movList(id,y,m)+'</div></div></div></div>';\n}\nfunction refreshEmp(){\n  var id=S.ui.emp,y=S.ui.y,m=S.ui.m;\n  var s=$('#sum');if(s)s.innerHTML=sumCard(id,y,m);\n  var mv=$('#movs');if(mv)mv.innerHTML=movList(id,y,m);\n}\n\n/* ---------- จ่ายเงิน ---------- */\nfunction vPay(){\n  var y=S.ui.y,m=S.ui.m,t=allMonth(y,m);\n  if(!S.emps.length)return '<div class=\"card empty\">ยังไม่มีพนักงาน</div>';\n  var rows=S.emps.map(function(e){\n    var s=monthStat(e.id,y,m);\n    return '<tr><td><span class=\"row\" style=\"flex-wrap:nowrap\"><span class=\"avatar\" style=\"background:'+e.color+';width:30px;height:30px;border-radius:9px;font-size:14px\">'+esc(init1(e.name))+'</span>'+esc(e.name)+'</span></td>'+\n      '<td class=\"r num\">'+kg(s.q)+'</td><td class=\"r num\">'+fmt(s.inc)+'</td><td class=\"r num pos\">'+(s.add?'+'+fmt(s.add):'—')+'</td>'+\n      '<td class=\"r num neg\">'+(s.adv?'−'+fmt(s.adv):'—')+'</td><td class=\"r num neg\">'+(s.ded?'−'+fmt(s.ded):'—')+'</td>'+\n      '<td class=\"r num\"><b>'+fmt(s.net)+'</b></td>'+\n      '<td><button class=\"btn sm '+(s.paid?'on':'warn')+'\" data-act=\"paid\" data-v=\"'+e.id+'\">'+(s.paid?'✓ จ่ายแล้ว':'ทำเครื่องหมายจ่าย')+'</button></td>'+\n      '<td><button class=\"btn sm\" data-act=\"slip\" data-v=\"'+e.id+'\">สลิป</button></td></tr>';\n  }).join('');\n  return '<div class=\"grid g3\"><div class=\"card kpi\"><div class=\"lb\">ยอดที่ต้องจ่ายทั้งหมด</div><div class=\"v\">'+fmt(t.net)+'<span class=\"u\">บาท</span></div></div>'+\n    '<div class=\"card kpi\"><div class=\"lb\">จ่ายแล้ว</div><div class=\"v pos\">'+fmt(t.paid)+'<span class=\"u\">บาท</span></div></div>'+\n    '<div class=\"card kpi\"><div class=\"lb\">คงเหลือต้องจ่าย</div><div class=\"v\" style=\"color:var(--amber)\">'+fmt(t.unpaid)+'<span class=\"u\">บาท</span></div></div></div>'+\n    '<div class=\"card\" style=\"margin-top:16px\"><div class=\"row\" style=\"justify-content:space-between;margin-bottom:12px\"><h2 style=\"margin:0\">ใบสรุปจ่ายเงิน · '+MTH[m-1]+' '+be(y)+'</h2>'+\n    '<button class=\"btn sm\" data-act=\"slipall\">คัดลอกสรุปทั้งหมด</button></div>'+\n    '<div class=\"tw\"><table><thead><tr><th>พนักงาน</th><th class=\"r\">กก.</th><th class=\"r\">ค่าปอก</th><th class=\"r\">เพิ่ม</th><th class=\"r\">เบิก</th><th class=\"r\">หัก</th><th class=\"r\">รับสุทธิ</th><th></th><th></th></tr></thead><tbody>'+rows+\n    '</tbody><tfoot><tr><td>รวม</td><td class=\"r num\">'+kg(t.q)+'</td><td class=\"r num\">'+fmt(t.inc)+'</td><td class=\"r num\">'+fmt(t.add)+'</td><td class=\"r num\">'+fmt(t.adv)+'</td><td class=\"r num\">'+fmt(t.ded)+'</td><td class=\"r num\">'+fmt(t.net)+'</td><td></td><td></td></tr></tfoot></table></div></div>';\n}\nfunction slipText(id,y,m){\n  var e=emp(id),s=monthStat(id,y,m),L=[];\n  L.push('สลิปค่าปอกกล้วยสุก — แม่ดอนรุ่งเรือง ฟู้ดส์');\n  L.push('ชื่อ: '+e.name);L.push('งวด: '+MTH[m-1]+' '+be(y));L.push('');\n  L.push('ทำงาน '+s.days+' วัน · ปอกได้รวม '+kg(s.q)+' กก.');\n  L.push('ค่าปอก: '+fmt(s.inc)+' บาท');\n  if(s.add)L.push('เงินเพิ่ม: +'+fmt(s.add)+' บาท');\n  S.mov.filter(function(x){return x.emp===id&&x.date.slice(0,7)===y+'-'+pad(m)}).sort(function(a,b){return a.date<b.date?-1:1}).forEach(function(x){\n    L.push('  - '+(+x.date.slice(8))+' '+MS[m-1]+' '+TYPES[x.type].n+(x.note?' ('+x.note+')':'')+': '+(TYPES[x.type].sign<0?'−':'+')+fmt(num(x.amt)));\n  });\n  L.push('เบิกล่วงหน้า: −'+fmt(s.adv)+' บาท');L.push('หักอื่นๆ: −'+fmt(s.ded)+' บาท');\n  L.push('────────────');L.push('รับสุทธิ: '+fmt(s.net)+' บาท');\n  return L.join('\\n');\n}\n\n/* ---------- รายปี ---------- */\nfunction vYear(){\n  var y=S.ui.y;\n  if(!S.emps.length)return '<div class=\"card empty\">ยังไม่มีพนักงาน</div>';\n  var mt=[],gt=0,gq=0;for(var m=0;m<12;m++)mt.push(0);\n  var rows=S.emps.map(function(e){\n    var ys=yearStat(e.id,y);gt+=ys.net;gq+=ys.q;\n    return '<tr><td>'+esc(shortName(e.name))+'</td>'+ys.months.map(function(s,i){mt[i]+=s.net;return '<td class=\"r num\">'+(s.net?fmt(s.net,0):'—')+'</td>'}).join('')+\n      '<td class=\"r num\"><b>'+fmt(ys.net,0)+'</b></td><td class=\"r num\">'+kg(ys.q)+'</td><td class=\"r num\">'+ys.days+'</td></tr>';\n  }).join('');\n  var ser=S.emps.map(function(e){return{n:shortName(e.name),c:e.color,v:yearStat(e.id,y).months.map(function(s){return s.net})}});\n  return '<div class=\"grid g4\"><div class=\"card kpi\"><div class=\"lb\">รับสุทธิทั้งปี '+be(y)+'</div><div class=\"v\">'+fmt(gt,0)+'<span class=\"u\">บาท</span></div></div>'+\n    '<div class=\"card kpi\"><div class=\"lb\">ปอกได้ทั้งปี</div><div class=\"v\">'+kg(gq)+'<span class=\"u\">กก.</span></div></div>'+\n    '<div class=\"card kpi\"><div class=\"lb\">เฉลี่ยต่อเดือน</div><div class=\"v\">'+fmt(gt/12,0)+'<span class=\"u\">บาท</span></div></div>'+\n    '<div class=\"card kpi\"><div class=\"lb\">เฉลี่ยต่อคน/เดือน</div><div class=\"v\">'+fmt(S.emps.length?gt/12/S.emps.length:0,0)+'<span class=\"u\">บาท</span></div></div></div>'+\n    '<div class=\"card\" style=\"margin-top:16px\"><h2>รับสุทธิรายเดือน ปี '+be(y)+' (บาท)</h2>'+legend()+stackChart(MS,ser,{label:'รับสุทธิรายเดือน'})+'</div>'+\n    '<div class=\"card\" style=\"margin-top:16px\"><h2>ตารางสรุปรายปี</h2><div class=\"tw\"><table><thead><tr><th>พนักงาน</th>'+MS.map(function(x){return '<th class=\"r\">'+x+'</th>'}).join('')+'<th class=\"r\">รวม</th><th class=\"r\">กก.</th><th class=\"r\">วัน</th></tr></thead><tbody>'+rows+\n    '</tbody><tfoot><tr><td>รวม</td>'+mt.map(function(v){return '<td class=\"r num\">'+fmt(v,0)+'</td>'}).join('')+'<td class=\"r num\">'+fmt(gt,0)+'</td><td class=\"r num\">'+kg(gq)+'</td><td></td></tr></tfoot></table></div></div>';\n}\n\n/* ---------- ตั้งค่า ---------- */\nfunction vSet(){\n  var list=S.emps.map(function(e){\n    return '<div class=\"row\" style=\"padding:10px 0;border-bottom:1px solid var(--line);flex-wrap:nowrap\" data-id=\"'+e.id+'\">'+\n      '<div class=\"avatar\" style=\"background:'+e.color+'\">'+esc(init1(e.name))+'</div>'+\n      '<div style=\"flex:1;min-width:0;display:flex;flex-direction:column;gap:8px\"><input class=\"inp sm\" data-act=\"ename\" value=\"'+esc(e.name)+'\" aria-label=\"ชื่อพนักงาน\">'+\n      '<div class=\"swatches\">'+COLORS.map(function(c){return '<button class=\"sw'+(c===e.color?' sel':'')+'\" style=\"background:'+c+'\" data-act=\"ecolor\" data-c=\"'+c+'\" aria-label=\"สี\"></button>'}).join('')+'</div></div>'+\n      '<button class=\"btn sm dan\" data-act=\"delemp\" data-v=\"'+e.id+'\">ลบ</button></div>';\n  }).join('')||'<div class=\"empty\">ยังไม่มีพนักงาน</div>';\n  return '<div class=\"grid g2\" style=\"align-items:start\"><div class=\"card\"><div class=\"row\" style=\"justify-content:space-between;margin-bottom:6px\"><h2 style=\"margin:0\">รายชื่อพนักงาน</h2><button class=\"btn pri sm\" data-act=\"addemp\">＋ เพิ่มพนักงาน</button></div>'+list+'</div>'+\n    '<div class=\"grid\"><div class=\"card\"><h2>ราคาเริ่มต้น</h2><div class=\"sub\">ใช้กับวันที่ยังไม่เคยบันทึก</div><div class=\"row\"><input class=\"inp r\" id=\"dp\" inputmode=\"decimal\" style=\"width:110px\" value=\"'+S.defPrice+'\"><span class=\"muted\">บาท / กก.</span><button class=\"btn sm\" data-act=\"savedp\">บันทึก</button></div></div>'+\n    '<div class=\"card\"><h2>ส่งออก / นำเข้า Excel</h2><div class=\"sub\">แก้ไขจำนวนมากใน Excel แล้วนำกลับเข้ามาได้ — ระบบจับคู่พนักงานจากชื่อ</div>'+\n    '<div class=\"row\"><button class=\"btn pri\" data-act=\"xlexp\">ส่งออกเป็น Excel (.xlsx)</button><button class=\"btn sm\" data-act=\"xlcopy\">คัดลอกเป็นตาราง</button></div>'+\n    '<div class=\"field mt\" style=\"margin-top:16px\"><label>นำเข้าไฟล์ (.xlsx / .csv)</label><div class=\"row\"><select class=\"inp sm\" id=\"xmode\"><option value=\"merge\">รวมกับข้อมูลเดิม</option><option value=\"replace\">แทนที่ข้อมูลทั้งหมด</option></select>'+\n    '<label class=\"btn sm\" style=\"cursor:pointer\">เลือกไฟล์<input type=\"file\" id=\"xf\" accept=\".xlsx,.xls,.csv\" style=\"display:none\"></label></div></div>'+\n    '<div class=\"muted\">ไฟล์มีชีต \"รายวัน\" และ \"เบิก-หัก\" วันที่ใช้รูปแบบ วว/ดด/ปปปป (พ.ศ. หรือ ค.ศ. ก็ได้) เพิ่มแถวหรือพนักงานใหม่ได้เลย</div></div>'+\n    '<div class=\"card\"><h2>สำรอง / กู้คืนข้อมูล</h2><div class=\"sub\">ข้อมูลหลักเก็บใน Cloudflare D1 · คัดลอกเก็บไว้อีกชั้นได้</div>'+\n    '<textarea class=\"inp\" id=\"bk\" rows=\"4\" style=\"width:100%;font-size:12px\" placeholder=\"วางข้อมูลสำรองที่นี่เพื่อกู้คืน\"></textarea>'+\n    '<div class=\"row mt\" style=\"margin-top:10px\"><button class=\"btn sm\" data-act=\"bkcopy\">คัดลอกข้อมูลสำรอง</button><button class=\"btn sm pri\" data-act=\"bkload\">กู้คืนจากข้อความ</button></div></div></div></div>';\n}\n\n/* ---------- ส่งออก / นำเข้า Excel ---------- */\nvar PENDING=null;\nfunction thDate(k){return k.slice(8)+'/'+k.slice(5,7)+'/'+be(+k.slice(0,4))}\nfunction buildWorkbook(){\n  var W=XLSX.utils,wb=W.book_new(),name={};\n  S.emps.forEach(function(e){name[e.id]=e.name});\n  var daily=[['พนักงาน','วันที่ (วว/ดด/ปปปป พ.ศ.)','กิโลกรัม','บาท/กก.','หยุด (1=หยุด)','รวมบาท (คำนวณเอง ไม่ต้องแก้)']];\n  S.emps.forEach(function(e){\n    Object.keys(S.recs[e.id]||{}).sort().forEach(function(k){\n      var r=S.recs[e.id][k];if(!r.h&&!num(r.q)&&num(r.p)===S.defPrice)return;\n      daily.push([e.name,thDate(k),r.h?0:num(r.q),num(r.p),r.h?1:0,Math.round(dayAmt(r)*100)/100]);\n    });\n  });\n  var mov=[['พนักงาน','วันที่ (วว/ดด/ปปปป พ.ศ.)','ประเภท (เบิก/หัก/เพิ่ม)','จำนวนเงิน','หมายเหตุ']];\n  S.mov.slice().sort(function(a,b){return a.date<b.date?-1:1}).forEach(function(x){\n    if(name[x.emp])mov.push([name[x.emp],thDate(x.date),x.type==='adv'?'เบิก':x.type==='ded'?'หัก':'เพิ่ม',num(x.amt),x.note||'']);\n  });\n  var emps=[['ชื่อพนักงาน','สี']].concat(S.emps.map(function(e){return [e.name,e.color]}));\n  var sum=[['พนักงาน','ปี พ.ศ.','เดือน','ทำงาน (วัน)','กิโลกรัม','ค่าปอก','เพิ่ม','เบิก','หัก','รับสุทธิ']];\n  var yrs={};Object.keys(S.recs).forEach(function(id){Object.keys(S.recs[id]).forEach(function(k){yrs[+k.slice(0,4)]=1})});\n  Object.keys(yrs).sort().forEach(function(y){S.emps.forEach(function(e){for(var m=1;m<=12;m++){\n    var s=monthStat(e.id,+y,m);if(s.inc||s.adv||s.ded||s.add)sum.push([e.name,be(+y),MTH[m-1],s.days,s.q,s.inc,s.add,s.adv,s.ded,s.net]);\n  }})});\n  [['รายวัน',daily,[24,22,12,10,14,22]],['เบิก-หัก',mov,[24,22,22,14,28]],['พนักงาน',emps,[28,12]],['สรุปรายเดือน (อ่านอย่างเดียว)',sum,[24,10,14,12,12,12,10,10,10,12]]].forEach(function(s){\n    var ws=W.aoa_to_sheet(s[1]);ws['!cols']=s[2].map(function(w){return{wch:w}});W.book_append_sheet(wb,ws,s[0]);\n  });\n  return wb;\n}\nfunction stamp(){var d=new Date();return d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())}\nasync function exportXlsx(){\n  if(typeof XLSX==='undefined'){toast('โหลดตัวสร้าง Excel ไม่สำเร็จ ลองรีเฟรชหน้า');return}\n  var buf=XLSX.write(buildWorkbook(),{bookType:'xlsx',type:'array'});\n  var fname='ค่าปอกกล้วย_'+stamp()+'.xlsx';\n  var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));\n  a.download=fname;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},4000);toast('ดาวน์โหลดไฟล์แล้ว');\n}\nfunction copyTable(){\n  var name={};S.emps.forEach(function(e){name[e.id]=e.name});\n  var L=['พนักงาน\\tวันที่\\tกิโลกรัม\\tบาท/กก.\\tหยุด'];\n  S.emps.forEach(function(e){Object.keys(S.recs[e.id]||{}).sort().forEach(function(k){var r=S.recs[e.id][k];L.push([e.name,thDate(k),r.h?0:num(r.q),num(r.p),r.h?1:0].join('\\t'))})});\n  copyText(L.join('\\n'),function(){toast('คัดลอกแล้ว — วางใน Excel ได้เลย')});\n}\n\n/* อ่านไฟล์ */\nfunction pDate(v){\n  if(v==null||v==='')return null;var y,m,d;\n  if(typeof v==='number'){var t=new Date(Math.round((v-25569)*86400)*1000);y=t.getUTCFullYear();m=t.getUTCMonth()+1;d=t.getUTCDate()}\n  else{\n    var s=String(v).trim().match(/^(\\d{1,4})\\D(\\d{1,2})\\D(\\d{1,4})/);if(!s)return null;\n    var a=+s[1],b=+s[2],c=+s[3];if(a>31){y=a;m=b;d=c}else{d=a;m=b;y=c}\n  }\n  if(y>2400)y-=543;else if(y<100)y+=1957;\n  if(m<1||m>12||d<1||d>dim(y,m))return null;\n  return dkey(y,m,d);\n}\nfunction pick(h,keys){for(var i=0;i<h.length;i++){var t=String(h[i]||'');for(var j=0;j<keys.length;j++)if(t.indexOf(keys[j])>=0)return i}return -1}\nfunction parseWb(wb){\n  var out={recs:[],mov:[],empNames:[],bad:0},seen={};\n  function addName(n){n=String(n||'').trim();if(n&&!seen[n]){seen[n]=1;out.empNames.push(n)}return n}\n  function rowsOf(ws){return XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:''})}\n  wb.SheetNames.forEach(function(sn){\n    var R=rowsOf(wb.Sheets[sn]);if(R.length<2)return;var h=R[0];\n    var ci=pick(h,['พนักงาน','ชื่อ']),di=pick(h,['วันที่']);\n    if(sn.indexOf('พนักงาน')===0&&di<0){\n      for(var i=1;i<R.length;i++){var n=addName(R[i][0]);if(n&&/^#[0-9a-f]{6}$/i.test(String(R[i][1]||'').trim()))out.color=out.color||{},out.color[n]=String(R[i][1]).trim()}\n      return;\n    }\n    if(ci<0||di<0)return;\n    var ti=pick(h,['ประเภท']),ai=pick(h,['จำนวนเงิน','จำนวน']),ni=pick(h,['หมายเหตุ']);\n    var qi=pick(h,['กิโล','กก']),pi=pick(h,['บาท/กก','ราคา']),hi=pick(h,['หยุด']);\n    for(var r=1;r<R.length;r++){\n      var row=R[r],nm=String(row[ci]||'').trim();if(!nm&&!row[di])continue;\n      var k=pDate(row[di]);if(!nm||!k){out.bad++;continue}\n      addName(nm);\n      if(ti>=0&&ai>=0){\n        var tt=String(row[ti]),ty=tt.indexOf('เบิก')>=0?'adv':tt.indexOf('หัก')>=0?'ded':(tt.indexOf('เพิ่ม')>=0||tt.indexOf('โบนัส')>=0)?'add':null;\n        var am=num(row[ai]);if(!ty||am<=0){out.bad++;continue}\n        out.mov.push({name:nm,date:k,type:ty,amt:am,note:ni>=0?String(row[ni]||'').trim():''});\n      }else if(qi>=0){\n        var qv=row[qi],hol=0;\n        if(hi>=0){var hv=String(row[hi]).trim().toLowerCase();hol=(hv&&hv!=='0'&&hv!=='ไม่'&&hv!=='false')?1:0}\n        if(typeof qv==='string'&&qv.indexOf('หยุด')>=0)hol=1;\n        out.recs.push({name:nm,key:k,q:hol?0:num(qv),p:pi>=0&&row[pi]!==''?num(row[pi]):S.defPrice,h:hol});\n      }\n    }\n  });\n  return out;\n}\nfunction readWb(buf,name){\n  /* .csv จาก Excel ไทยมักเป็น TIS-620 / มี BOM — ถอดรหัสเองให้ถูกก่อน */\n  if(/\\.(csv|txt|tsv)$/i.test(name||'')){\n    var txt;\n    try{txt=new TextDecoder('utf-8',{fatal:true}).decode(buf)}\n    catch(e){try{txt=new TextDecoder('windows-874').decode(buf)}catch(e2){txt=new TextDecoder('utf-8').decode(buf)}}\n    return XLSX.read(txt.replace(/^\\uFEFF/,''),{type:'string',raw:true});\n  }\n  return XLSX.read(buf,{type:'array'});\n}\nfunction onFile(file,mode){\n  if(typeof XLSX==='undefined'){toast('โหลดตัวอ่าน Excel ไม่สำเร็จ ลองรีเฟรชหน้า');return}\n  var fr=new FileReader();\n  fr.onload=function(){\n    try{\n      var wb=readWb(fr.result,file.name),p=parseWb(wb);\n      if(!p.recs.length&&!p.mov.length){toast('ไม่พบข้อมูลที่อ่านได้ในไฟล์นี้');return}\n      var have={};S.emps.forEach(function(e){have[e.name.trim()]=1});\n      p.news=p.empNames.filter(function(n){return !have[n]});p.mode=mode;PENDING=p;\n      modal('<h2>ตรวจสอบก่อนนำเข้า</h2><div class=\"rows\" style=\"margin-bottom:12px\"><div><span>รายวัน</span><span class=\"num\">'+p.recs.length+' แถว</span></div><div><span>เบิก/หัก/เพิ่ม</span><span class=\"num\">'+p.mov.length+' รายการ</span></div>'+\n        '<div><span>พนักงานใหม่</span><span>'+(p.news.length?esc(p.news.join(', ')):'ไม่มี')+'</span></div>'+(p.bad?'<div><span>แถวที่อ่านไม่ได้ (ข้าม)</span><span class=\"num neg\">'+p.bad+'</span></div>':'')+'</div>'+\n        (mode==='replace'?'<p class=\"neg\" style=\"font-size:14px\">โหมดแทนที่: ข้อมูลเดิมทั้งหมดจะถูกลบและใช้ข้อมูลในไฟล์แทน</p>':'<p class=\"muted\">โหมดรวม: วันที่ซ้ำจะถูกเขียนทับด้วยค่าจากไฟล์ วันอื่นคงเดิม</p>')+\n        '<div class=\"row mt\" style=\"justify-content:flex-end\"><button class=\"btn\" data-act=\"close\">ยกเลิก</button><button class=\"btn '+(mode==='replace'?'dan':'pri')+'\" data-act=\"doimport\">นำเข้า</button></div>');\n    }catch(e){toast('อ่านไฟล์ไม่สำเร็จ')}\n  };\n  fr.readAsArrayBuffer(file);\n}\nfunction applyImport(){\n  var p=PENDING;if(!p)return;PENDING=null;\n  var byName={};S.emps.forEach(function(e){byName[e.name.trim()]=e});\n  var emps=p.mode==='replace'?[]:S.emps.slice();\n  p.empNames.forEach(function(n){\n    var e=byName[n];\n    if(!e){e={id:'e'+uid(),name:n,color:(p.color&&p.color[n])||COLORS[(S.emps.length+emps.length)%COLORS.length],note:''};byName[n]=e;S.recs[e.id]={}}\n    if(emps.indexOf(e)<0)emps.push(e);\n  });\n  if(p.mode==='replace'){var keep={};emps.forEach(function(e){keep[e.id]=1});\n    Object.keys(S.recs).forEach(function(id){if(!keep[id])delete S.recs[id]});\n    emps.forEach(function(e){S.recs[e.id]={}});S.mov=[];\n    Object.keys(S.paid).forEach(function(k){if(!keep[k.split('|')[0]])delete S.paid[k]});}\n  S.emps=emps;\n  p.recs.forEach(function(r){var id=byName[r.name].id;S.recs[id]=S.recs[id]||{};S.recs[id][r.key]={q:r.q,p:r.p,h:r.h}});\n  p.mov.forEach(function(x){\n    var id=byName[x.name].id;\n    var dup=S.mov.some(function(o){return o.emp===id&&o.date===x.date&&o.type===x.type&&num(o.amt)===x.amt&&(o.note||'')===x.note});\n    if(!dup)S.mov.push({id:uid(),emp:id,type:x.type,date:x.date,amt:x.amt,note:x.note});\n  });\n  if(!S.emps.some(function(e){return e.id===S.ui.emp}))S.ui.emp=S.emps[0]&&S.emps[0].id;\n  save();closeModal();render();toast('นำเข้าแล้ว');\n}\ndocument.addEventListener('change',function(ev){\n  var el=ev.target;if(el.id!=='xf'||!el.files[0])return;\n  var md=($('#xmode')||{}).value||'merge';onFile(el.files[0],md);el.value='';\n});\n\n/* ---------- แสดงผลหลัก ---------- */\nfunction render(){\n  if(!S)return;\n  renderPeriod();renderTabs();renderAcct();\n  var f={dash:vDash,emp:vEmp,pay:vPay,year:vYear,set:vSet}[S.ui.tab]||vDash;\n  $('#view').innerHTML=f();\n}\nfunction go(patch){for(var k in patch)S.ui[k]=patch[k];save();render()}\n\n/* ---------- หน้าต่างย่อย ---------- */\nfunction modal(html){\n  $('#layer').innerHTML='<div class=\"mask\" data-act=\"maskclose\"><div class=\"modal\" role=\"dialog\" aria-modal=\"true\">'+html+'</div></div>';\n  var f=$('#layer input,#layer select');if(f&&f.type!=='checkbox')try{f.focus()}catch(e){}\n}\nfunction closeModal(){$('#layer').innerHTML=''}\nfunction confirmBox(title,text,okLabel,act,v){\n  modal('<h2>'+esc(title)+'</h2><p class=\"muted\" style=\"font-size:14px;color:var(--ink2)\">'+esc(text)+'</p><div class=\"row mt\" style=\"justify-content:flex-end\"><button class=\"btn\" data-act=\"close\">ยกเลิก</button><button class=\"btn dan\" data-act=\"'+act+'\" data-v=\"'+esc(v||'')+'\">'+esc(okLabel)+'</button></div>');\n}\nfunction copyText(t,done){\n  function fb(){\n    var ta=document.createElement('textarea');ta.value=t;ta.style.cssText='position:fixed;opacity:0';document.body.appendChild(ta);ta.select();\n    try{document.execCommand('copy');done&&done()}catch(e){toast('เลือกข้อความแล้วกด Ctrl+C')}ta.remove();\n  }\n  try{navigator.clipboard.writeText(t).then(function(){done&&done()},fb)}catch(e){fb()}\n}\n\n/* ---------- ฟอร์ม ---------- */\nfunction movForm(){\n  var y=S.ui.y,m=S.ui.m,n=dim(y,m),today=new Date(),dd=(today.getFullYear()===y&&today.getMonth()+1===m)?today.getDate():1;\n  var ds='';for(var d=1;d<=n;d++)ds+='<option value=\"'+d+'\"'+(d===dd?' selected':'')+'>'+d+' '+MS[m-1]+'</option>';\n  modal('<h2>เพิ่มรายการ · '+esc(shortName(emp(S.ui.emp).name))+'</h2>'+\n    '<div class=\"field\"><label>ประเภท</label><select class=\"inp\" id=\"mt\"><option value=\"adv\">เบิกล่วงหน้า (หักจากค่าปอก)</option><option value=\"ded\">หักอื่นๆ</option><option value=\"add\">เงินเพิ่ม / โบนัส</option></select></div>'+\n    '<div class=\"grid g2\" style=\"gap:12px\"><div class=\"field\"><label>วันที่</label><select class=\"inp\" id=\"md\">'+ds+'</select></div>'+\n    '<div class=\"field\"><label>จำนวนเงิน (บาท)</label><input class=\"inp r\" id=\"ma\" inputmode=\"decimal\" placeholder=\"0\"></div></div>'+\n    '<div class=\"field\"><label>หมายเหตุ (ถ้ามี)</label><input class=\"inp\" id=\"mn\" placeholder=\"เช่น เบิกค่าน้ำมัน\"></div>'+\n    '<div class=\"row\" style=\"justify-content:flex-end\"><button class=\"btn\" data-act=\"close\">ยกเลิก</button><button class=\"btn pri\" data-act=\"savemov\">บันทึก</button></div>');\n}\nfunction empForm(){\n  modal('<h2>เพิ่มพนักงาน</h2><div class=\"field\"><label>ชื่อ-นามสกุล</label><input class=\"inp\" id=\"en\" placeholder=\"เช่น นางสมศรี ใจดี\"></div>'+\n    '<div class=\"field\"><label>สีประจำตัว</label><div class=\"swatches\" id=\"ec\">'+COLORS.map(function(c,i){return '<button class=\"sw'+(i===S.emps.length%COLORS.length?' sel':'')+'\" style=\"background:'+c+'\" data-act=\"pickc\" data-c=\"'+c+'\" aria-label=\"สี\"></button>'}).join('')+'</div></div>'+\n    '<div class=\"row mt\" style=\"justify-content:flex-end\"><button class=\"btn\" data-act=\"close\">ยกเลิก</button><button class=\"btn pri\" data-act=\"saveemp\">เพิ่ม</button></div>');\n}\n\n/* ---------- เหตุการณ์คลิก ---------- */\ndocument.addEventListener('click',function(ev){\n  var el=ev.target.closest('[data-act]');if(!el)return;\n  var a=el.dataset.act;if(a==='retry'){loadRemote(true);return}if(!S)return;var v=el.dataset.v,y=S.ui.y,m=S.ui.m,id=S.ui.emp;\n  if(a==='maskclose'){if(ev.target===el)closeModal();return}\n  switch(a){\n    case 'tab':go({tab:v});break;\n    case 'mprev':if(m===1)go({m:12,y:y-1});else go({m:m-1});break;\n    case 'mnext':if(m===12)go({m:1,y:y+1});else go({m:m+1});break;\n    case 'goemp':go({tab:'emp',emp:v});break;\n    case 'pick':go({emp:v});break;\n    case 'close':closeModal();break;\n    case 'hol':\n      var tr=el.closest('tr'),k=v;S.recs[id]=S.recs[id]||{};\n      var r=S.recs[id][k]||(S.recs[id][k]={q:0,p:S.defPrice,h:0});\n      r.h=r.h?0:1;save();\n      tr.outerHTML=dayRow(id,y,m,+k.slice(8));refreshEmp();break;\n    case 'setprice':\n      modal('<h2>ตั้งราคาต่อกิโลกรัมทั้งเดือน</h2><div class=\"field\"><label>บาท / กก. ('+MTH[m-1]+' '+be(y)+')</label><input class=\"inp r\" id=\"sp\" inputmode=\"decimal\" value=\"'+S.defPrice+'\"></div><div class=\"row mt\" style=\"justify-content:flex-end\"><button class=\"btn\" data-act=\"close\">ยกเลิก</button><button class=\"btn pri\" data-act=\"dosetprice\">ใช้ราคานี้</button></div>');break;\n    case 'dosetprice':\n      var p=num($('#sp').value);S.recs[id]=S.recs[id]||{};\n      for(var d=1;d<=dim(y,m);d++){var kk=dkey(y,m,d);var rr=S.recs[id][kk]||(S.recs[id][kk]={q:0,p:p,h:0});rr.p=p}\n      save();closeModal();render();toast('ตั้งราคาแล้ว');break;\n    case 'clearm':confirmBox('ล้างข้อมูลเดือนนี้?','ลบจำนวน กก. และวันหยุดของ '+emp(id).name+' ใน '+MTH[m-1]+' '+be(y)+' ทั้งหมด (รายการเบิก/หักไม่ถูกลบ)','ล้างข้อมูล','doclear');break;\n    case 'doclear':\n      for(var d2=1;d2<=dim(y,m);d2++)delete (S.recs[id]||{})[dkey(y,m,d2)];\n      save();closeModal();render();toast('ล้างแล้ว');break;\n    case 'addmov':movForm();break;\n    case 'savemov':\n      var amt=num($('#ma').value);if(amt<=0){toast('กรุณาใส่จำนวนเงิน');break}\n      S.mov.push({id:uid(),emp:id,type:$('#mt').value,date:dkey(y,m,+$('#md').value),amt:amt,note:$('#mn').value.trim()});\n      save();closeModal();refreshEmp();toast('บันทึกแล้ว');break;\n    case 'delmov':S.mov=S.mov.filter(function(x){return x.id!==v});save();refreshEmp();break;\n    case 'paid':var pk=v+'|'+y+'-'+pad(m);if(S.paid[pk])delete S.paid[pk];else S.paid[pk]=1;save();render();break;\n    case 'slip':\n      var tx=slipText(v,y,m);\n      modal('<h2>สลิปค่าปอก</h2><div class=\"slip\" id=\"sl\">'+esc(tx)+'</div><div class=\"row mt\" style=\"justify-content:flex-end\"><button class=\"btn\" data-act=\"close\">ปิด</button><button class=\"btn pri\" data-act=\"copyslip\" data-v=\"'+v+'\">คัดลอกข้อความ</button></div>');break;\n    case 'copyslip':copyText(slipText(v,y,m),function(){toast('คัดลอกแล้ว')});break;\n    case 'slipall':copyText(S.emps.map(function(e){return slipText(e.id,y,m)}).join('\\n\\n==========\\n\\n'),function(){toast('คัดลอกสรุปทั้งหมดแล้ว')});break;\n    case 'addemp':empForm();break;\n    case 'pickc':\n      $('#ec').querySelectorAll('.sw').forEach(function(b){b.classList.toggle('sel',b===el)});break;\n    case 'saveemp':\n      var nm=$('#en').value.trim();if(!nm){toast('กรุณาใส่ชื่อ');break}\n      var sc=$('#ec .sel'),ne={id:'e'+uid(),name:nm,color:sc?sc.dataset.c:COLORS[0],note:''};\n      S.emps.push(ne);S.recs[ne.id]={};if(!S.ui.emp)S.ui.emp=ne.id;save();closeModal();render();toast('เพิ่มพนักงานแล้ว');break;\n    case 'ecolor':\n      var eid=el.closest('[data-id]').dataset.id;emp(eid).color=el.dataset.c;save();render();break;\n    case 'delemp':confirmBox('ลบพนักงาน?','ลบ '+emp(v).name+' พร้อมข้อมูลรายวันและรายการเบิก/หักทั้งหมด ย้อนกลับไม่ได้','ลบพนักงาน','dodelemp',v);break;\n    case 'dodelemp':\n      S.emps=S.emps.filter(function(e){return e.id!==v});delete S.recs[v];\n      S.mov=S.mov.filter(function(x){return x.emp!==v});\n      Object.keys(S.paid).forEach(function(k){if(k.indexOf(v+'|')===0)delete S.paid[k]});\n      if(S.ui.emp===v)S.ui.emp=S.emps[0]&&S.emps[0].id;\n      save();closeModal();render();break;\n    case 'xlexp':exportXlsx();break;\n    case 'xlcopy':copyTable();break;\n    case 'doimport':applyImport();break;\n    case 'savedp':S.defPrice=num($('#dp').value)||1.5;save();toast('บันทึกราคาเริ่มต้นแล้ว');break;\n    case 'bkcopy':copyText(JSON.stringify(S),function(){toast('คัดลอกข้อมูลสำรองแล้ว')});break;\n    case 'bkload':\n      try{var o=JSON.parse($('#bk').value);if(!o.emps||!o.recs)throw 0;S=o;load2();save();render();toast('กู้คืนข้อมูลแล้ว')}\n      catch(e){toast('ข้อมูลไม่ถูกต้อง')}break;\n  }\n});\n\n/* ---------- เหตุการณ์เปลี่ยนค่า ---------- */\ndocument.addEventListener('change',function(ev){\n  if(!S)return;var el=ev.target,a=el.dataset&&el.dataset.act;\n  if(a==='selm')go({m:+el.value});\n  else if(a==='sely')go({y:+el.value});\n});\ndocument.addEventListener('input',function(ev){\n  var el=ev.target;if(!S)return;\n  if(el.dataset.act==='ename'){var e=emp(el.closest('[data-id]').dataset.id);e.name=el.value;save();return}\n  var f=el.dataset.f;if(!f)return;\n  var tr=el.closest('tr'),k=tr.dataset.k,id=S.ui.emp;\n  S.recs[id]=S.recs[id]||{};\n  var r=S.recs[id][k]||(S.recs[id][k]={q:0,p:S.defPrice,h:0});\n  r[f]=num(el.value);save();\n  var amt=dayAmt(r),c=tr.querySelector('.amt');c.textContent=amt?fmt(amt):'—';\n  refreshEmp();\n});\ndocument.addEventListener('keydown',function(ev){\n  if(ev.key==='Escape')closeModal();\n  if(ev.key==='Enter'&&ev.target.classList&&ev.target.classList.contains('qin')){\n    ev.preventDefault();\n    var ins=[].slice.call(document.querySelectorAll('#rows .qin:not([disabled])')),i=ins.indexOf(ev.target);\n    if(ins[i+1]){ins[i+1].focus();ins[i+1].select()}\n  }\n});\n\n/* ---------- เริ่มต้น ---------- */\nboot();\n</script>\n\n</body>\n</html>\n";

/**
 * API บัญชีค่าปอกกล้วยสุก — Cloudflare Worker + D1
 *
 *  GET  /api/rev                       -> { rev }
 *  GET  /api/data                      -> ข้อมูลทั้งหมด
 *  POST /api/sync    { ...diff }       -> { rev }          
 *
 * ไม่มีระบบล็อกอิน: ใครมีลิงก์ก็เปิดและแก้ไขได้
 */

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const YM_RE = /^\d{4}-\d{2}$/;
const MAX_OPS = 6000;
const CHUNK = 90;

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
  });

/* ---------- ตัวช่วยฐานข้อมูล ---------- */
const str = (v, max) => (typeof v === 'string' ? v.slice(0, max) : '');
const numv = (v, d = 0) => (Number.isFinite(+v) ? +v : d);

async function runBatches(db, stmts) {
  for (let i = 0; i < stmts.length; i += CHUNK) await db.batch(stmts.slice(i, i + CHUNK));
}
async function getRev(db) {
  const r = await db.prepare("SELECT value FROM settings WHERE key='rev'").first();
  return r ? +r.value : 1;
}

