const q1 = (x) => "'" + String(x).replace(/'/g, "''") + "'";
let ready = null;
function ensureDb(env) {
  if (!ready) {
    ready = (async () => {
      const db = env.DB;
      await db.batch(SCHEMA.map((x) => db.prepare(x)));
      if (await db.prepare("SELECT 1 FROM settings WHERE key='seeded'").first()) return;
      const n = await db.prepare('SELECT COUNT(*) AS c FROM employees').first();
      if (!n.c) {
        const st = [];
        SEED.emps.forEach((e, i) => st.push(db.prepare(`INSERT OR IGNORE INTO employees(id,name,color,note,sort) VALUES(${q1(e[0])},${q1(e[1])},${q1(e[2])},'',${i + 1})`)));
        const dim = (m) => new Date(2026, m, 0).getDate();
        const p2 = (x) => (x < 10 ? '0' + x : '' + x);
        SEED.emps.forEach((e) => {
          const vals = SEED.data[e[0]].split(',');
          let i = 0;
          const rows = [];
          for (let m = 1; m <= 12; m++)
            for (let d = 1; d <= dim(m); d++) {
              const v = +vals[i++];
              rows.push(`(${q1(e[0])},'2026-${p2(m)}-${p2(d)}',${v < 0 ? 0 : v},1.5,${v < 0 ? 1 : 0})`);
            }
          for (let k = 0; k < rows.length; k += 200)
            st.push(db.prepare('INSERT OR IGNORE INTO records(emp_id,date,qty,price,holiday) VALUES' + rows.slice(k, k + 200).join(',')));
        });
        await db.batch(st);
      }
      await db.prepare("INSERT OR IGNORE INTO settings(key,value) VALUES('seeded','1')").run();
    })().catch((e) => { ready = null; throw e; });
  }
  return ready;
}

/* ---------- เส้นทาง ---------- */
async function getData(env) {
  const db = env.DB;
  const [emps, recs, mov, paid, set] = await db.batch([
    db.prepare('SELECT id,name,color,note FROM employees ORDER BY sort,rowid'),
    db.prepare('SELECT emp_id,date,qty,price,holiday FROM records ORDER BY emp_id,date'),
    db.prepare('SELECT id,emp_id,date,type,amount,note FROM movements ORDER BY date'),
    db.prepare('SELECT emp_id,ym FROM payments'),
    db.prepare('SELECT key,value FROM settings'),
  ]);
  const s = {};
  set.results.forEach((r) => (s[r.key] = r.value));
  return json({
    rev: +(s.rev || 1),
    defPrice: numv(s.defPrice, 1.5),
    emps: emps.results,
    recs: recs.results.map((r) => [r.emp_id, r.date, r.qty, r.price, r.holiday]),
    mov: mov.results.map((r) => ({ id: r.id, emp: r.emp_id, date: r.date, type: r.type, amt: r.amount, note: r.note })),
    paid: paid.results.map((r) => r.emp_id + '|' + r.ym),
  });
}

/**
 * รับเฉพาะส่วนที่เปลี่ยน (diff) จากหน้าเว็บ:
 * { emps:{up:[{id,name,color,note,sort}],del:[id]},
 *   recs:{up:[[emp,date,q,p,h]],del:[[emp,date]]},
 *   mov:{up:[{id,emp,date,type,amt,note}],del:[id]},
 *   paid:{on:["emp|ym"],off:["emp|ym"]}, defPrice:number }
 */
async function sync(env, req) {
  let b;
  try { b = await req.json(); } catch { return json({ error: 'bad request' }, 400); }
  const db = env.DB;
  const S = [];
  const g = (o, k) => (o && Array.isArray(o[k]) ? o[k] : []);
  const total = g(b.emps, 'up').length + g(b.emps, 'del').length + g(b.recs, 'up').length + g(b.recs, 'del').length +
    g(b.mov, 'up').length + g(b.mov, 'del').length + g(b.paid, 'on').length + g(b.paid, 'off').length;
  if (total > MAX_OPS) return json({ error: 'ข้อมูลที่ส่งมามากเกินไปในครั้งเดียว' }, 413);

  // ลบพนักงานก่อน (cascade ลบข้อมูลรายวัน/เบิก/จ่ายของคนนั้น)
  g(b.emps, 'del').forEach((id) => S.push(db.prepare('DELETE FROM employees WHERE id=?').bind(str(id, 40))));
  g(b.emps, 'up').forEach((e) => {
    if (!e || !str(e.id, 40) || !str(e.name, 200)) return;
    S.push(
      db.prepare(
        `INSERT INTO employees(id,name,color,note,sort) VALUES(?,?,?,?,?)
         ON CONFLICT(id) DO UPDATE SET name=excluded.name,color=excluded.color,note=excluded.note,sort=excluded.sort`
      ).bind(str(e.id, 40), str(e.name, 200), /^#[0-9a-fA-F]{6}$/.test(e.color) ? e.color : '#1f6f4a', str(e.note, 500), numv(e.sort))
    );
  });
  g(b.recs, 'del').forEach((r) => {
    if (Array.isArray(r) && DATE_RE.test(r[1])) S.push(db.prepare('DELETE FROM records WHERE emp_id=? AND date=?').bind(str(r[0], 40), r[1]));
  });
  g(b.recs, 'up').forEach((r) => {
    if (!Array.isArray(r) || !DATE_RE.test(r[1])) return;
    S.push(
      db.prepare(
        `INSERT INTO records(emp_id,date,qty,price,holiday)
         SELECT ?1,?2,?3,?4,?5 WHERE EXISTS (SELECT 1 FROM employees WHERE id=?1)
         ON CONFLICT(emp_id,date) DO UPDATE SET qty=excluded.qty,price=excluded.price,holiday=excluded.holiday`
      ).bind(str(r[0], 40), r[1], Math.max(0, numv(r[2])), Math.max(0, numv(r[3], 1.5)), r[4] ? 1 : 0)
    );
  });
  g(b.mov, 'del').forEach((id) => S.push(db.prepare('DELETE FROM movements WHERE id=?').bind(str(id, 40))));
  g(b.mov, 'up').forEach((m) => {
    if (!m || !str(m.id, 40) || !DATE_RE.test(m.date) || !['adv', 'ded', 'add'].includes(m.type)) return;
    S.push(
      db.prepare(
        `INSERT INTO movements(id,emp_id,date,type,amount,note)
         SELECT ?1,?2,?3,?4,?5,?6 WHERE EXISTS (SELECT 1 FROM employees WHERE id=?2)
         ON CONFLICT(id) DO UPDATE SET date=excluded.date,type=excluded.type,amount=excluded.amount,note=excluded.note`
      ).bind(str(m.id, 40), str(m.emp, 40), m.date, m.type, Math.max(0, numv(m.amt)), str(m.note, 300))
    );
  });
  g(b.paid, 'off').forEach((k) => {
    const [e, ym] = String(k).split('|');
    if (YM_RE.test(ym || '')) S.push(db.prepare('DELETE FROM payments WHERE emp_id=? AND ym=?').bind(str(e, 40), ym));
  });
  g(b.paid, 'on').forEach((k) => {
    const [e, ym] = String(k).split('|');
    if (YM_RE.test(ym || '')) S.push(db.prepare('INSERT OR IGNORE INTO payments(emp_id,ym) SELECT ?1,?2 WHERE EXISTS (SELECT 1 FROM employees WHERE id=?1)').bind(str(e, 40), ym));
  });
  if (b.defPrice != null && Number.isFinite(+b.defPrice) && +b.defPrice > 0) {
    S.push(db.prepare("INSERT INTO settings(key,value) VALUES('defPrice',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(String(+b.defPrice)));
  }
  if (!S.length) return json({ rev: await getRev(db) });
  S.push(db.prepare("INSERT INTO settings(key,value) VALUES('rev','2') ON CONFLICT(key) DO UPDATE SET value=CAST(value AS INTEGER)+1"));
  try {
    await runBatches(db, S);
  } catch (e) {
    return json({ error: 'บันทึกไม่สำเร็จ: ' + (e && e.message ? e.message : e) }, 500);
  }
  return json({ rev: await getRev(db) });
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith('/api/')) {
      if (url.pathname === '/' || url.pathname === '/index.html')
        return new Response(HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' } });
      return new Response('Not found', { status: 404 });
    }
    try {
      if (url.pathname === '/api/health') return json({ ok: true });
      if (!env.DB) return json({ error: 'ยังไม่ได้เชื่อมฐานข้อมูล D1 (ตัวแปร Binding ต้องชื่อ DB)' }, 500);
      await ensureDb(env);
      if (url.pathname === '/api/rev' && req.method === 'GET') return json({ rev: await getRev(env.DB) });
      if (url.pathname === '/api/data' && req.method === 'GET') return await getData(env);
      if (url.pathname === '/api/sync' && req.method === 'POST') return await sync(env, req);
      return json({ error: 'not found' }, 404);
    } catch (e) {
      return json({ error: 'server error: ' + (e && e.message ? e.message : e) }, 500);
    }
  },
};
